#!/usr/bin/env node
/**
 * Apply pending database migrations from ./drizzle (generated by `npm run db:generate`).
 * Production runs this as the one-shot `migrate` service before the app starts.
 * Safe to run repeatedly: already-applied migrations are skipped.
 */
const url = process.env.DATABASE_URL;
if (!url) {
  console.error("DATABASE_URL is not set");
  process.exit(1);
}

const started = Date.now();
try {
  if (url.startsWith("pglite:")) {
    const { PGlite } = await import("@electric-sql/pglite");
    const { drizzle } = await import("drizzle-orm/pglite");
    const { migrate } = await import("drizzle-orm/pglite/migrator");
    const location = url.slice("pglite://".length);
    const client = location === "memory" ? new PGlite() : new PGlite(location);
    await migrate(drizzle(client), { migrationsFolder: "drizzle" });
    await client.close();
  } else {
    const { default: postgres } = await import("postgres");
    const { drizzle } = await import("drizzle-orm/postgres-js");
    const { migrate } = await import("drizzle-orm/postgres-js/migrator");
    const client = postgres(url, { max: 1, onnotice: () => {} });
    await migrate(drizzle(client), { migrationsFolder: "drizzle" });
    await client.end({ timeout: 5 });
  }
  console.log(`[migrate] database is up to date (${Date.now() - started} ms)`);
} catch (err) {
  console.error("[migrate] failed:", err);
  process.exit(1);
}
